// Données de contenu générées par scripts/content.mjs, importées via l'alias `@generated`
// (next.config.js) : src/generated/dev/ en développement (brouillons), src/generated/prod/ au
// build. Pas de chemin TypeScript (tsconfig) pour cet alias : il ne doit dépendre que du mode
// de Next. Les types précis sont appliqués par les modules d'accès (src/lib/content/*).
declare module '@generated/projects.json' {
  const data: { note: string; includeDrafts: boolean; projects: unknown[] };
  export default data;
}

declare module '@generated/simple.json' {
  const data: { note: string; includeDrafts: boolean; products: unknown[] };
  export default data;
}

declare module '@generated/index.json' {
  const data: { note: string; includeDrafts: boolean; entries: unknown[] };
  export default data;
}
